CREATE TABLE model_alias_target_versions (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    alias_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    revision BIGINT NOT NULL CHECK(revision BETWEEN 1 AND 9007199254740991),
    source_revision BIGINT,
    action VARCHAR(20) NOT NULL CHECK(action IN('migration_current','published','disabled','paused','resumed','retargeted','rolled_back')),
    deployment_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    deployment_revision BIGINT NOT NULL CHECK(deployment_revision BETWEEN 1 AND 9007199254740991),
    model_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    model_kind VARCHAR(20) NOT NULL CHECK(model_kind IN('approved_base','merged_lora')),
    catalog_digest VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL CHECK(REGEXP_LIKE(catalog_digest,'^[a-f0-9]{64}$','c')),
    serving_recipe_sha256 VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin,
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    UNIQUE(tenant_id,workspace_id,alias_id,revision),
    KEY model_alias_target_page_idx(tenant_id,workspace_id,alias_id,created_at DESC,id DESC),
    FOREIGN KEY(tenant_id,workspace_id,alias_id,revision) REFERENCES model_alias_history(tenant_id,workspace_id,alias_id,revision),
    FOREIGN KEY(tenant_id,workspace_id,alias_id,source_revision) REFERENCES model_alias_target_versions(tenant_id,workspace_id,alias_id,revision),
    CHECK((action='rolled_back' AND source_revision IS NOT NULL AND source_revision<revision AND source_revision>=1) OR (action<>'rolled_back' AND source_revision IS NULL)),
    FOREIGN KEY(tenant_id,workspace_id,deployment_id) REFERENCES deployments(tenant_id,workspace_id,id),
    FOREIGN KEY(tenant_id,workspace_id,model_id,model_kind,catalog_digest) REFERENCES model_versions(tenant_id,workspace_id,id,kind,catalog_digest),
    CHECK((model_kind='approved_base' AND serving_recipe_sha256 IS NULL) OR (model_kind='merged_lora' AND serving_recipe_sha256 IS NOT NULL AND REGEXP_LIKE(serving_recipe_sha256,'^[a-f0-9]{64}$','c'))),
    CONSTRAINT model_alias_target_versions_id_canonical CHECK(id IS NULL OR REGEXP_LIKE(id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_alias_target_versions_tenant_id_canonical CHECK(tenant_id IS NULL OR REGEXP_LIKE(tenant_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_alias_target_versions_workspace_id_canonical CHECK(workspace_id IS NULL OR REGEXP_LIKE(workspace_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_alias_target_versions_alias_id_canonical CHECK(alias_id IS NULL OR REGEXP_LIKE(alias_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_alias_target_versions_deployment_id_canonical CHECK(deployment_id IS NULL OR REGEXP_LIKE(deployment_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT model_alias_target_versions_model_id_canonical CHECK(model_id IS NULL OR REGEXP_LIKE(model_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
